-- Mod-authored World Congress splash descriptions, de_DE overlay.
-- Baseline in CivVAccess_CongressDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_MISSING"] = "Keine Beschreibung für dieses Bild."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_SPECIAL_SESSION_START_WORLD_CONGRESS"] =
    "Eine tagende Versammlung, von der Rückseite des Saals über die Köpfe der Zuschauer hinweg betrachtet. Vorn sitzen Delegierte um einen langen, rotbespannten Tisch auf einem Podium mit Teppich, an jedem Platz ein weißes Blatt Papier. Eine Gestalt in weißen Gewändern und weißem Kopfschmuck steht am Kopfende des Tisches, um das Wort an den Raum zu richten, neben ihr ein Mann mit dunklem Bart. Die Zuschauer sitzen ihr auf Reihen von Holzstühlen gegenüber, Turbane und Käppchen und bloße Köpfe nebeneinander. Weitere Beobachter schauen zwischen blassen Säulen entlang der rechten Wand herein."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_FAIR"] =
    "Ein riesiges Riesenrad wächst rechts oben aus dem Bild heraus, geschlossene Fahrgastgondeln hängen an seinem Rand. Sein Fuß ragt hinter einem großen Bogen aus genietetem grünem Eisen hervor, der eine blasse Wand mit dem Schriftzug FERRIS WHEEL überspannt. Unten auf der breiten staubigen Promenade schlendern Besucher der Weltausstellung: Frauen in langen Kleidern, Männer in Übermänteln und Melonen und Zylindern. Links säumen niedrige Ausstellungsgebäude mit bemalten Schildern den Weg, wo sich in der Ferne unter einem blassblauen Himmel eine weiße Kuppelhalle erhebt."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_CONGRESSDESC_LEAGUE_PROJECT_WORLD_GAMES"] =
    "Die ersten Schritte eines Rennens: Vier Läufer stoßen sich mit gesenkten Köpfen vom Start ab, auf einer dunklen Bahn, die den Vordergrund überquert. Links dahinter steht der Starter in einem langen weißen Mantel, die Pistole noch rauchend erhoben. Vollbesetzte Tribünen füllen den gesamten Hintergrund, die Menge als Farbtupfer angedeutet. Rechts säumen weiße Leiterstände und hohe Masten die Bahn, dahinter dehnt sich das Grün des Innenfelds."
